mapper.select:
SELECT id AS database_id, business_id, name, description, prompt,
created_at, updated_at
FROM skill WHERE business_id = #{skillId}

SELECT COUNT(*) FROM project_skill
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND skill_id = #{skillId}

mapper.update:
UPDATE project_skill SET enabled = #{enabled},
updated_at = CURRENT_TIMESTAMP
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND skill_id = #{skillId}

mapper.delete:
DELETE FROM project_skill
WHERE tenant_id = #{tenantId} AND project_id = #{projectId}
AND skill_id = #{skillId}
